#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_compare_equal_arrival_lower_priority_first(void) {
    // Setup: create two process nodes with equal arrival time
    // Node a has lower priority (higher priority) than node b
    node *a = (node *)malloc(sizeof(node));
    node *b = (node *)malloc(sizeof(node));

    // Initialize node a: arrival time 5, priority 1 (high priority)
    a->AT = 5;
    a->priority = 1;
    // Initialize node b: arrival time 5, priority 3 (lower priority)
    b->AT = 5;
    b->priority = 3;

    // Test: call compare function
    bool result = compare(a, b);

    // Assertions
    // Since arrival times are equal and a->priority (1) < b->priority (3),
    // compare should return true (a comes before b)
    TEST_ASSERT_TRUE(result);

    // Cleanup
    free(a);
    free(b);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_compare_equal_arrival_lower_priority_first);
    return UNITY_END();
}

